workflow.mutation:
mutation RepairPajamasGuide($id: ID!, $article: ArticleUpdateInput!) {
  articleUpdate(id: $id, article: $article) {
    article { id body updatedAt }
    userErrors { code field message }
  }
}

workflow.source_query:
query PajamasGuideSource($query: String!, $first: Int!, $after: String) {
  shop { name myshopifyDomain }
  articles(first: $first, after: $after, query: $query) {
    nodes { id title handle body isPublished publishedAt updatedAt blog { id handle title } }
    pageInfo { hasNextPage endCursor }
  }
}
